package com.acme.billing.retry;

import java.time.Duration;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Exponential backoff with full jitter for calls to the payment provider.
 * Immutable; build instances with {@link #builder()}.
 */
public final class RetryPolicy {

    private final int maxAttempts;
    private final Duration baseDelay;
    private final Duration maxDelay;
    private final Set<Integer> retryableStatuses;

    private RetryPolicy(Builder b) {
        this.maxAttempts = b.maxAttempts;
        this.baseDelay = b.baseDelay;
        this.maxDelay = b.maxDelay;
        this.retryableStatuses = Set.copyOf(b.retryableStatuses);
    }

    public static Builder builder() {
        return new Builder();
    }

    public boolean shouldRetry(int attempt, int httpStatus) {
        return attempt < maxAttempts && retryableStatuses.contains(httpStatus);
    }

    public Duration delayFor(int attempt) {
        if (attempt < 1) {
            throw new IllegalArgumentException("attempt starts at 1");
        }
        long capped = Math.min(maxDelay.toMillis(), baseDelay.toMillis() * (1L << Math.min(attempt - 1, 20)));
        return Duration.ofMillis(ThreadLocalRandom.current().nextLong(capped + 1));
    }

    public int maxAttempts() {
        return maxAttempts;
    }

    public static final class Builder {
        private int maxAttempts = 4;
        private Duration baseDelay = Duration.ofMillis(200);
        private Duration maxDelay = Duration.ofSeconds(10);
        private Set<Integer> retryableStatuses = Set.of(408, 425, 429, 500, 502, 503, 504);

        public Builder maxAttempts(int value) {
            if (value < 1) {
                throw new IllegalArgumentException("maxAttempts must be >= 1");
            }
            this.maxAttempts = value;
            return this;
        }

        public Builder baseDelay(Duration value) {
            this.baseDelay = Objects.requireNonNull(value);
            return this;
        }

        public Builder maxDelay(Duration value) {
            this.maxDelay = Objects.requireNonNull(value);
            return this;
        }

        public Builder retryableStatuses(Set<Integer> value) {
            this.retryableStatuses = Objects.requireNonNull(value);
            return this;
        }

        public RetryPolicy build() {
            if (maxDelay.compareTo(baseDelay) < 0) {
                throw new IllegalStateException("maxDelay < baseDelay");
            }
            return new RetryPolicy(this);
        }
    }
}

//! Write-ahead log: length-prefixed, CRC-checked records appended to segment files.

use std::fs::{File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

const MAX_RECORD: u32 = 16 * 1024 * 1024;

pub struct Wal {
    dir: PathBuf,
    segment: u64,
    writer: BufWriter<File>,
    written: u64,
    segment_limit: u64,
}

impl Wal {
    pub fn open(dir: impl AsRef<Path>, segment_limit: u64) -> io::Result<Self> {
        let dir = dir.as_ref().to_path_buf();
        std::fs::create_dir_all(&dir)?;
        let segment = Self::segments(&dir)?.last().copied().unwrap_or(0);
        let file = OpenOptions::new().create(true).append(true).open(Self::path(&dir, segment))?;
        let written = file.metadata()?.len();
        Ok(Self { dir, segment, writer: BufWriter::new(file), written, segment_limit })
    }

    pub fn append(&mut self, payload: &[u8]) -> io::Result<()> {
        let len = u32::try_from(payload.len()).map_err(|_| io::Error::other("record too large"))?;
        if len > MAX_RECORD {
            return Err(io::Error::other("record too large"));
        }
        if self.written + u64::from(len) + 8 > self.segment_limit {
            self.rotate()?;
        }
        self.writer.write_all(&len.to_le_bytes())?;
        self.writer.write_all(&crc32fast::hash(payload).to_le_bytes())?;
        self.writer.write_all(payload)?;
        self.written += u64::from(len) + 8;
        Ok(())
    }

    pub fn sync(&mut self) -> io::Result<()> {
        self.writer.flush()?;
        self.writer.get_ref().sync_data()
    }

    pub fn replay(dir: impl AsRef<Path>, mut f: impl FnMut(&[u8])) -> io::Result<usize> {
        let mut count = 0;
        for seg in Self::segments(dir.as_ref())? {
            let mut r = BufReader::new(File::open(Self::path(dir.as_ref(), seg))?);
            let mut header = [0u8; 8];
            loop {
                match r.read_exact(&mut header) {
                    Ok(()) => {}
                    Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => break,
                    Err(e) => return Err(e),
                }
                let len = u32::from_le_bytes(header[..4].try_into().unwrap());
                let crc = u32::from_le_bytes(header[4..].try_into().unwrap());
                let mut buf = vec![0; len as usize];
                if r.read_exact(&mut buf).is_err() || crc32fast::hash(&buf) != crc {
                    break; // torn write at the tail: stop replay here
                }
                f(&buf);
                count += 1;
            }
        }
        Ok(count)
    }

    fn rotate(&mut self) -> io::Result<()> {
        self.sync()?;
        self.segment += 1;
        let file = OpenOptions::new().create(true).append(true).open(Self::path(&self.dir, self.segment))?;
        self.writer = BufWriter::new(file);
        self.written = 0;
        Ok(())
    }

    fn path(dir: &Path, segment: u64) -> PathBuf {
        dir.join(format!("{segment:020}.wal"))
    }

    fn segments(dir: &Path) -> io::Result<Vec<u64>> {
        let mut v: Vec<u64> = std::fs::read_dir(dir)?
            .filter_map(|e| e.ok()?.file_name().to_str()?.strip_suffix(".wal")?.parse().ok())
            .collect();
        v.sort_unstable();
        Ok(v)
    }
}

