type Limiter struct {
	shards [shardCount]shard
	rate   float64
	burst  float64
	now    func() time.Time
	ttl    time.Duration
}

const shardCount = 64

type shard struct {
	mu      sync.Mutex
	buckets map[string]*bucket
}

func New(rate, burst float64, ttl time.Duration) *Limiter {
	l := &Limiter{rate: rate, burst: burst, now: time.Now, ttl: ttl}
	for i := range l.shards {
		l.shards[i].buckets = make(map[string]*bucket)
	}
	return l
}

func (l *Limiter) shardFor(key string) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return &l.shards[h.Sum32()%shardCount]
}

// Allow reports whether one token can be taken for key.
func (l *Limiter) Allow(key string) bool {
	return l.AllowN(key, 1)
}

// AllowN reports whether n tokens can be taken for key at once.
func (l *Limiter) AllowN(key string, n float64) bool {
	s := l.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()
	now := l.now()
	b, ok := s.buckets[key]
	if !ok {
		b = &bucket{tokens: l.burst, last: now}
		s.buckets[key] = b
	}
	b.tokens = math.Min(l.burst, b.tokens+now.Sub(b.last).Seconds()*l.rate)
	b.last = now
	if b.tokens < n {
		return false
	}
	b.tokens -= n
	return true
}

// Sweep deletes buckets idle for longer than the TTL; call it periodically.
func (l *Limiter) Sweep() (removed int) {
	cutoff := l.now().Add(-l.ttl)
	for i := range l.shards {
		s := &l.shards[i]
		s.mu.Lock()
		for k, b := range s.buckets {
			if b.last.Before(cutoff) {
				delete(s.buckets, k)
				removed++
			}
		}
		s.mu.Unlock()
	}
	return removed
}

