# Compare pinned versions with the latest releases on PyPI (package names only are sent).
import json, re, sys, urllib.request
from concurrent.futures import ThreadPoolExecutor

PIN = re.compile(r'^\s*([A-Za-z0-9_.\-]+)(?:\[[^\]]*\])?\s*==\s*([^\s;#]+)')

def pins(paths):
    for path in paths:
        with open(path) as fh:
            for line in fh:
                m = PIN.match(line)
                if m:
                    yield path, m.group(1), m.group(2)

def latest(name):
    url = f"https://pypi.org/pypi/{name}/json"
    try:
        with urllib.request.urlopen(url, timeout=10) as r:
            info = json.load(r)["info"]
            return info["version"], info.get("yanked", False)
    except Exception as exc:
        return f"error: {exc.__class__.__name__}", False

def key(v):
    return tuple(int(x) if x.isdigit() else 0 for x in re.split(r'[.+-]', v)[:4])

rows = list(pins(sys.argv[1:]))
with ThreadPoolExecutor(max_workers=8) as pool:
    results = list(pool.map(lambda r: latest(r[1]), rows))

outdated = 0
print(f"{'package':28} {'pinned':>12} {'latest':>12}  file")
for (path, name, pinned), (new, _) in zip(rows, results):
    if new.startswith("error") or key(new) <= key(pinned):
        continue
    major = key(new)[0] != key(pinned)[0]
    outdated += 1
    print(f"{name:28} {pinned:>12} {new:>12}  {path}{'  MAJOR' if major else ''}")
print(f"\n{outdated} of {len(rows)} pins are behind")
EOF
